from __future__ import annotations
from dataclasses import dataclass
from math import sqrt
from typing import Any, Dict, Optional

# Regime-specific V_t CSV paths — plain-GBM paths in the `V_smooth` column,
# generated by `data/v_gbm.py generate-all`.
FV_CSV = {
    "calm":     "data/fv_calm.csv",
    "stressed": "data/fv_stressed.csv",
}

# Per-regime σ_v: per-step (1-min) log-return std of V_t. Direct fit on the
# 1-min processed ES front-month MID series (data/v_gbm.py calibrate). MT
# also uses this as its reference 1-min return std — by construction the
# empirical 1-min mid log-return std equals σ_v (that is what σ_v is
# calibrated against), so no separate MT_REF dict is needed.
SIGMA_V = {
    "calm":     0.00029732584831326943,
    "stressed": 0.001822674698246824,
}

V0 = {
    "calm":     2463.125,
    "stressed": 3253.875,
}

# MBP-10 geometric placement-depth — diagnostic only (D20). Live limit-
# order placement uses the calibrated log-normal `depth_mean`.
P_ZI = {
    "calm":     0.5430,
    "stressed": 0.3431,
}

# MM top-of-book quote size (D31). Structural — pinned not calibrated;
# `mm_p_edge` is the calibrated MM dial (D48).
MM_QTY = {
    "calm":     2,
    "stressed": 2,
}

# Uniform `U[1, qty_max]` order-size cap (ODD §Stochasticity). D49 reverted
# (Pareto degraded Hill under our linear-impact LOB matching). Flat 10
# matches the ODD baseline; volume scaling to empirical ES is handled by
# the `VOLUME_LOT` relabeling below, not by per-order qty.
QTY_MAX = {
    "calm":     10,
    "stressed": 10,
}

# D50 — Institutional-lot relabeling. The model treats each `qty` unit as
# one 50-contract institutional ES block. Empirical ES per-minute volume
# is ~2,500 (calm) / ~5,000 (stressed); the model's raw per-minute volume
# at qty_max=10 is ~35 / ~40, ≈50–70× short. Reading one model unit as
# 50 contracts (the typical ES block-trade lot in CME data — Eisler-
# Bouchaud-Kockelkoren 2012 reference distribution) brings reported volume
# into the empirical envelope without changing LOB dynamics, log-returns,
# ACFs or Hill (all invariant under multiplicative qty rescaling).
# Applied only at REPORTING and CAPITAL-RATIO computation, never inside
# the LOB / matching engine.
VOLUME_LOT = 50

# CME E-mini ES futures contract multiplier — $50 per index point. Used in
# capital-ratio / notional computations (Stage 4a). The "USD notional per
# (model qty unit · price point)" is therefore VOLUME_LOT · CONTRACT_USD
# = 50 · 50 = $2,500 per model-qty-point.
CONTRACT_USD = 50.0

# Almgren-Chriss impact coefficients — calibrated from BBO-1m via
# data/impact.py (Hasbrouck 1991 / AC 2000 linear-impact regression).
# NOT currently wired into any agent (AC execution tabled under D10f in
# favour of POV; see ModelParams.mm_pov). Kept here for documentation +
# future re-enable. γ both regimes empirically negative (post-trade price
# reversion dominates at K=30 min, Hasbrouck 1991 / BMP 2002 transient-only
# finding) → floored at 0.
ETA_TEMP = {
    "calm":     1.5094e-4,
    "stressed": 7.0064e-4,
}
GAMMA_PERM = {
    "calm":     0.0,   # raw β_perm = -1.17e-5; transient-only regime
    "stressed": 0.0,   # raw β_perm = -1.38e-4; transient-only regime
}

# ZI rates (zi_alpha limit / zi_mu market / zi_delta cancel) are CALIBRATED
# per regime (D21 — all three entered the loop when the MM was dropped and
# ZI became a primary price driver). The ODD-baseline values (0.15 / 0.025 /
# 0.025) are the ModelParams defaults and the calibration-bound anchors.

# Pin point for FT belief dispersion: σ_fundamental = ft_sigma_c · σ_v · v0
# = one daily V_t std (Chiarella heterogeneous-beliefs at the daily-news
# scale; ABIDES ValueAgent precedent). Calibrating ft_sigma_c was tried and
# landed near √(390·5) (one weekly std); the structural pin removes a
# calibrated parameter at negligible cost (FT belief dispersion is a design
# choice, not a market observable).
FT_SIGMA_C_DEFAULT = sqrt(390.0)

# Calibrated behavioural parameters — the 6-d theta per regime (D18b/D18c/D48):
# depth_mean, depth_sigma, zi_alpha, zi_mu, zi_delta, mm_p_edge. Copied from
# `results[regime].theta_stage2` in output/calibrated_params.json. RE-COPY
# after any re-calibration — this dict is the single source the simulator entry
# points (run_simulation.py, analysis_long_run.py) read from.
#
# STALE — both entries below are PRE-D48 placeholders and do NOT match a
# current-model validated run:
#   - stressed: the validated D48 theta (D=21.67) IS in
#     output/calibrated_params.json but was NEVER copied here — copy it back
#     (note the rails: depth_sigma -> 0.95, mm_p_edge -> 1.43).
#   - calm: never run at 6-d (absent from the JSON — a stressed-only run
#     overwrote it). mm_p_edge=4.0 is the D31 default; the rest is the pre-D48
#     5-d overnight stage-2 theta.
CALIBRATED = {
    "calm": dict(
        depth_mean=5.714897, depth_sigma=0.3,
        zi_alpha=0.472154, zi_mu=0.037421, zi_delta=0.361801,
        mm_p_edge=4.0,
    ),
    "stressed": dict(
        depth_mean=7.873318, depth_sigma=0.3,
        zi_alpha=0.495703, zi_mu=0.061506, zi_delta=0.079857,
        mm_p_edge=4.0,
    ),
}


# ── Clearing-tier constants (D28) ────────────────────────────────────────────
