CCP_CASH = 10_000_000               # ODD MatchingEngine cash
BCM_CASH_RANGE = (5e9, 1e10)        # ODD BankingClearingMember:    U[5B, 10B]
NBCM_CASH_RANGE = (5e6, 1e7)        # ODD NonBankingClearingMember: U[5M, 10M]

